// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.leo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.junit.jupiter.api.Test;

/**
 * Robustness properties of {@link LeoConfidenceModel}: invalid samples are no-ops, corrections are learned in log space
 * (so symmetric errors cancel instead of biasing the multiplier), an empty execution cannot collapse a correction below
 * one row, a single outlier cannot cap confidence forever, and evidence keeps decaying when the epoch counter
 * regresses.
 */
class LeoConfidenceModelRobustnessTest {

	@Test
	void nonFiniteSamplesMustNotCountAsPerfectEvidence() {
		LeoConfidenceModel learned = LeoConfidenceModel.empty().observe(10.0d, 1_000.0d, 10.0d, 1_000.0d, 1L);
		LeoConfidenceModel polluted = learned;
		for (int i = 0; i < 5; i++) {
			polluted = polluted.observe(Double.NaN, Double.NaN, Double.NaN, Double.NaN, 2L + i);
		}
		String state = "before: correction=" + learned.rowCorrectionRatio() + " confidence=" + learned.confidence()
				+ " samples=" + learned.sampleCount() + "; after 5 NaN samples: correction="
				+ polluted.rowCorrectionRatio() + " confidence=" + polluted.confidence() + " samples="
				+ polluted.sampleCount();
		assertEquals(learned.rowCorrectionRatio(), polluted.rowCorrectionRatio(), 1.0e-9d,
				"invalid samples must not erase a learned correction: " + state);
		assertTrue(polluted.confidence() <= learned.confidence(),
				"invalid samples must not raise confidence: " + state);
		assertEquals(learned.sampleCount(), polluted.sampleCount(), "invalid samples must not count: " + state);
		assertEquals(learned.lastEpoch(), polluted.lastEpoch(), "invalid samples must not refresh the epoch");
	}

	@Test
	void infiniteAndNegativeSamplesAreNoOps() {
		LeoConfidenceModel learned = LeoConfidenceModel.empty()
				.observe(10.0d, 1_000.0d, 10.0d, 1_000.0d, 1L)
				.observe(10.0d, 900.0d, 10.0d, 900.0d, 2L);
		List<double[]> invalid = List.of(
				new double[] { Double.POSITIVE_INFINITY, 10.0d, 10.0d, 10.0d },
				new double[] { 10.0d, Double.NEGATIVE_INFINITY, 10.0d, 10.0d },
				new double[] { 10.0d, 10.0d, Double.NaN, 10.0d },
				new double[] { 10.0d, 10.0d, 10.0d, -1.0d },
				new double[] { -5.0d, 10.0d, 10.0d, 10.0d });
		for (double[] sample : invalid) {
			LeoConfidenceModel after = learned.observe(sample[0], sample[1], sample[2], sample[3], 50L);
			assertEquals(learned.sampleCount(), after.sampleCount());
			assertEquals(learned.rowCorrectionRatio(), after.rowCorrectionRatio(), 0.0d);
			assertEquals(learned.workCorrectionRatio(), after.workCorrectionRatio(), 0.0d);
			assertEquals(learned.confidence(), after.confidence(), 0.0d);
			assertEquals(learned.lastEpoch(), after.lastEpoch());
		}
	}

	@Test
	void symmetricPlanFlipErrorsMustNotBiasTheCorrectionRatio() {
		// Plan flips alternate a 100x under-estimate and a 100x over-estimate: geometric mean error is 1.
		LeoConfidenceModel model = LeoConfidenceModel.empty();
		StringBuilder trace = new StringBuilder();
		for (int i = 0; i < 20; i++) {
			model = i % 2 == 0 ? model.observe(1.0d, 100.0d, 1.0d, 100.0d, i)
					: model.observe(100.0d, 1.0d, 100.0d, 1.0d, i);
			trace.append(String.format("%.3f ", model.rowCorrectionRatio()));
		}
		double ratio = model.rowCorrectionRatio();
		assertTrue(ratio >= 0.1d && ratio <= 10.0d,
				"linear-space EWMA must not drift to a large multiplier for log-symmetric errors; trace=" + trace);
	}

	@Test
	void reciprocalRatiosAverageToUnityInLogSpace() {
		double[] ratios = { 3.0d, 0.5d, 1.5d, 1.0d / 3.0d, 2.0d, 1.0d / 1.5d };
		LeoConfidenceModel model = LeoConfidenceModel.empty();
		for (int round = 0; round < 4; round++) {
			for (int i = 0; i < ratios.length; i++) {
				model = model.observe(100.0d, 100.0d * ratios[i], 100.0d, 100.0d * ratios[i], round * 10L + i);
			}
		}
		assertTrue(model.rowCorrectionRatio() >= 0.5d && model.rowCorrectionRatio() <= 2.0d,
				"reciprocal ratios must cancel: " + model.rowCorrectionRatio());
		assertTrue(model.workCorrectionRatio() >= 0.5d && model.workCorrectionRatio() <= 2.0d,
				"reciprocal work ratios must cancel: " + model.workCorrectionRatio());
	}

	@Test
	void oneEmptyExecutionMustNotCollapseTheCorrectionBelowOneRow() {
		LeoConfidenceModel model = LeoConfidenceModel.empty().observe(50.0d, 0.0d, 50.0d, 0.0d, 1L);
		double correctedRows = 50.0d * model.rowCorrectionRatio();
		assertTrue(correctedRows >= 1.0d,
				"a single zero-row execution should not correct a 50-row estimate to " + correctedRows
						+ " (ratio=" + model.rowCorrectionRatio() + ", confidence=" + model.confidence() + ")");
	}

	@Test
	void zeroThenAccurateSamplesRecoverTowardUnity() {
		LeoConfidenceModel model = LeoConfidenceModel.empty().observe(50.0d, 0.0d, 50.0d, 0.0d, 1L);
		for (int i = 0; i < 5; i++) {
			model = model.observe(100.0d, 100.0d, 100.0d, 100.0d, 2L + i);
		}
		assertTrue(model.rowCorrectionRatio() >= 0.9d && model.rowCorrectionRatio() <= 1.1d,
				"five accurate samples must pull the correction back toward 1: " + model.rowCorrectionRatio());
	}

	@Test
	void oneOutlierMustNotCapConfidenceForeverAfterManyAccurateSamples() {
		LeoConfidenceModel model = LeoConfidenceModel.empty().observe(1.0d, 100_000.0d, 1.0d, 100_000.0d, 1L);
		for (int i = 0; i < 50; i++) {
			model = model.observe(100.0d, 100.0d, 100.0d, 100.0d, 2L + i);
		}
		assertTrue(model.confidence() >= 0.5d,
				"after 50 accurate samples confidence is " + model.confidence() + " (rowQErrorMax="
						+ model.rowQErrorMax() + ", correction=" + model.rowCorrectionRatio() + ")");
		assertTrue(model.rowQErrorMax() >= 100_000.0d, "the historical maximum stays available for diagnostics");
	}

	@Test
	void confidenceMustStillDecayWhenTheEpochCounterRegresses() {
		LeoConfidenceModel model = LeoConfidenceModel.empty();
		for (int i = 0; i < 10; i++) {
			model = model.observe(100.0d, 120.0d, 100.0d, 120.0d, 1_000_000L);
		}
		double decayed = model.decayedConfidence(10L, 4_096L);
		assertTrue(decayed < model.confidence(),
				"epoch regression (store rebuilt/sidecar mismatch) leaves confidence undecayed forever: "
						+ decayed);
	}

	@Test
	void decayIsMonotoneInEpochDistanceInBothDirections() {
		LeoConfidenceModel model = LeoConfidenceModel.empty();
		for (int i = 0; i < 10; i++) {
			model = model.observe(100.0d, 120.0d, 100.0d, 120.0d, 1_000L);
		}
		assertEquals(model.confidence(), model.decayedConfidence(1_000L, 64L), 0.0d);
		double previous = model.confidence();
		for (long distance : new long[] { 1L, 8L, 64L, 512L, 999L }) {
			double backwards = model.decayedConfidence(1_000L - distance, 64L);
			double forwards = model.decayedConfidence(1_000L + distance, 64L);
			assertEquals(forwards, backwards, 1.0e-12d, "decay must depend on distance only; distance=" + distance);
			assertTrue(backwards < previous, "decay must be monotone in distance; distance=" + distance);
			previous = backwards;
		}
	}

	@Test
	void persistedRoundTripPreservesTheLearnedState() {
		LeoConfidenceModel model = LeoConfidenceModel.empty()
				.observe(1.0d, 100_000.0d, 1.0d, 100_000.0d, 1L)
				.observe(100.0d, 100.0d, 100.0d, 100.0d, 2L)
				.observe(100.0d, 250.0d, 100.0d, 250.0d, 3L);
		LeoConfidenceModel restored = LeoConfidenceModel.fromPersisted(model.sampleCount(),
				model.rowCorrectionRatio(), model.workCorrectionRatio(), model.rowQErrorMean(), model.rowQErrorMax(),
				model.rowQErrorDecayed(), model.workQErrorMean(), model.workQErrorMax(), model.workQErrorDecayed(),
				model.logRatioVariance(), model.lastEpoch(), model.confidence());
		assertEquals(model.sampleCount(), restored.sampleCount());
		assertEquals(model.rowCorrectionRatio(), restored.rowCorrectionRatio(), 0.0d);
		assertEquals(model.workCorrectionRatio(), restored.workCorrectionRatio(), 0.0d);
		assertEquals(model.rowQErrorMax(), restored.rowQErrorMax(), 0.0d);
		assertEquals(model.rowQErrorDecayed(), restored.rowQErrorDecayed(), 0.0d);
		assertEquals(model.workQErrorDecayed(), restored.workQErrorDecayed(), 0.0d);
		assertEquals(model.logRatioVariance(), restored.logRatioVariance(), 0.0d);
		assertEquals(model.lastEpoch(), restored.lastEpoch());
		assertEquals(model.confidence(), restored.confidence(), 0.0d);
		// the restored model keeps learning exactly like the live one
		LeoConfidenceModel liveNext = model.observe(100.0d, 300.0d, 100.0d, 300.0d, 4L);
		LeoConfidenceModel restoredNext = restored.observe(100.0d, 300.0d, 100.0d, 300.0d, 4L);
		assertEquals(liveNext.rowCorrectionRatio(), restoredNext.rowCorrectionRatio(), 1.0e-12d);
		assertEquals(liveNext.confidence(), restoredNext.confidence(), 1.0e-12d);
	}

	@Test
	void persistedGarbageIsSanitizedAndConfidenceRecomputed() {
		LeoConfidenceModel restored = LeoConfidenceModel.fromPersisted(4L, Double.NaN, -3.0d, 0.5d,
				Double.POSITIVE_INFINITY, 1_000.0d, Double.NaN, Double.NaN, 50.0d, -1.0d, -7L, Double.NaN);
		assertEquals(4L, restored.sampleCount());
		assertEquals(1.0d, restored.rowCorrectionRatio(), 0.0d, "invalid ratio falls back to 1");
		assertEquals(1.0d, restored.workCorrectionRatio(), 0.0d, "negative ratio falls back to 1");
		assertEquals(1.0d, restored.rowQErrorMax(), 0.0d, "q-error below 1 or non-finite falls back to 1");
		assertTrue(restored.rowQErrorDecayed() <= restored.rowQErrorMax(), "decayed q-error never exceeds the max");
		assertTrue(restored.workQErrorDecayed() <= restored.workQErrorMax());
		assertEquals(0.0d, restored.logRatioVariance(), 0.0d, "negative variance falls back to 0");
		assertEquals(0L, restored.lastEpoch(), "negative epoch is clamped");
		double recomputed = 0.35d + 3 * 0.075d;
		assertEquals(recomputed, restored.confidence(), 1.0e-12d,
				"non-finite persisted confidence is recomputed from the sanitized state");
		assertEquals(LeoConfidenceModel.empty(), LeoConfidenceModel.fromPersisted(0L, 2.0d, 2.0d, 1.0d, 1.0d,
				1.0d, 1.0d, 1.0d, 1.0d, 0.0d, 5L, 0.5d), "no samples means the empty model");
	}

	@Test
	void regressedEpochReanchorsTheTimeline() {
		LeoConfidenceModel model = LeoConfidenceModel.empty()
				.observe(100.0d, 120.0d, 100.0d, 120.0d, 1_000_000L)
				.observe(100.0d, 120.0d, 100.0d, 120.0d, 5L);
		assertEquals(5L, model.lastEpoch(), "a sample from a regressed epoch counter must re-anchor lastEpoch");
		assertEquals(model.confidence(), model.decayedConfidence(5L, 64L), 0.0d);
	}
}
